create extension if not exists pgcrypto;
create type public.flight_status as enum ('on_time','check_in','boarding','last_call','gate_closed','departed');
create table public.rooms(id uuid primary key default gen_random_uuid(),code text unique not null check(length(trim(code)) between 1 and 20),destination text not null check(length(trim(destination)) between 1 and 100),subtitle text,icon_key text,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.teachers(id uuid primary key default gen_random_uuid(),name text unique not null check(length(trim(name)) between 2 and 120),enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.class_schedules(id uuid primary key default gen_random_uuid(),class_code text unique not null check(length(trim(class_code)) between 1 and 40),teacher_id uuid not null references public.teachers(id) on delete restrict,room_id uuid not null references public.rooms(id) on delete restrict,weekday smallint not null check(weekday between 1 and 7),start_time time not null,end_time time not null,active_from date not null,active_until date,enabled boolean not null default true,manual_status public.flight_status,manual_status_date date,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_time>start_time),check(active_until is null or active_until>=active_from),check((manual_status is null)=(manual_status_date is null)));
create table public.app_settings(id uuid primary key default '00000000-0000-0000-0000-000000000001',display_lead_minutes int not null default 120 check(display_lead_minutes between 1 and 720),checkin_minutes_before int not null default 30 check(checkin_minutes_before between 1 and 720),boarding_minutes_before int not null default 10 check(boarding_minutes_before between 1 and 720),last_call_minutes_before int not null default 3 check(last_call_minutes_before between 1 and 720),gate_closed_minutes_after_start int not null default 5 check(gate_closed_minutes_after_start between 1 and 180),retain_after_end_minutes int not null default 60 check(retain_after_end_minutes between 1 and 720),page_rotation_seconds int not null default 12 check(page_rotation_seconds between 3 and 300),updated_at timestamptz not null default now(),check(display_lead_minutes>=checkin_minutes_before and checkin_minutes_before>=boarding_minutes_before and boarding_minutes_before>=last_call_minutes_before));
create index class_schedules_day_active_idx on public.class_schedules(weekday,enabled,active_from,active_until);
create index class_schedules_teacher_idx on public.class_schedules(teacher_id);
create index class_schedules_room_idx on public.class_schedules(room_id);
create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end $$;
create trigger rooms_updated before update on public.rooms for each row execute function public.touch_updated_at();
create trigger teachers_updated before update on public.teachers for each row execute function public.touch_updated_at();
create trigger schedules_updated before update on public.class_schedules for each row execute function public.touch_updated_at();
create trigger settings_updated before update on public.app_settings for each row execute function public.touch_updated_at();
alter table public.rooms enable row level security;alter table public.teachers enable row level security;alter table public.class_schedules enable row level security;alter table public.app_settings enable row level security;
grant usage on schema public to anon;grant select on public.rooms,public.teachers,public.class_schedules,public.app_settings to anon;
create policy rooms_read on public.rooms for select to anon using(true);create policy teachers_read on public.teachers for select to anon using(true);create policy schedules_read on public.class_schedules for select to anon using(true);create policy settings_read on public.app_settings for select to anon using(true);
revoke insert,update,delete on public.rooms,public.teachers,public.class_schedules,public.app_settings from anon,authenticated;
create or replace function public.set_class_manual_status(schedule_id uuid,teacher_id uuid,new_status public.flight_status default null) returns void language plpgsql security definer set search_path='' as $$ begin update public.class_schedules set manual_status=new_status,manual_status_date=case when new_status is null then null else (now() at time zone 'America/Sao_Paulo')::date end where id=schedule_id and class_schedules.teacher_id=set_class_manual_status.teacher_id and enabled and weekday=extract(isodow from now() at time zone 'America/Sao_Paulo') and active_from<=(now() at time zone 'America/Sao_Paulo')::date and (active_until is null or active_until>=(now() at time zone 'America/Sao_Paulo')::date);if not found then raise exception 'Turma inválida para este professor ou dia';end if;end $$;
revoke all on function public.set_class_manual_status(uuid,uuid,public.flight_status) from public;grant execute on function public.set_class_manual_status(uuid,uuid,public.flight_status) to anon;
