blic.teachers t on t.name=x.teacher join public.rooms r on r.code=x.room on conflict(class_code) do nothing;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='class_schedules') then alter publication supabase_realtime add table public.class_schedules;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='rooms') then alter publication supabase_realtime add table public.rooms;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='teachers') then alter publication supabase_realtime add table public.teachers;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='app_settings') then alter publication supabase_realtime add table public.app_settings;end if;end $$;
